template <int count>
struct SplineCoeffs {
    float a[count];
    float b[count];
    float c[count];
    float d[count];
};

struct WaveProfileCoeffs {
    SplineCoeffs<16> y;
    SplineCoeffs<16> z;
};

enum WaveEmitterEnum {
    WAVE_EM_NONE,
    WAVE_EM_CREST
};

struct WaveEmitter {
    WaveEmitterEnum type;
    float x;
    float y;
    float z;
};

struct vector3d {
    float x, y, z;
    vector3d(float X, float Y, float Z) : x(X), y(Y), z(Z) {}
};

enum WavePerturbTypeEnum {
    WAVE_PerturbTypeSurge,
    WAVE_PerturbTypeTongue,
    WAVE_PerturbTypeCurl,
    WAVE_PerturbTypeBig,
    WAVE_PerturbTypeSmall,
    WAVE_PerturbTypeDouble,
    WAVE_PerturbTypeMax
};

enum WavePerturbStageEnum {
    WAVE_PerturbStageNone,
    WAVE_PerturbStageDo,
    WAVE_PerturbStageHold,
    WAVE_PerturbStageCollapse,
    WAVE_PerturbStageWait,
    WAVE_PerturbStageUndo,
    WAVE_PerturbStageMax
};

enum WaveStageEnum {
    WAVE_StageNone,
    WAVE_StageStable
};

struct WaveBreakInfoStruct {
    bool onoff;
    WavePerturbTypeEnum type;
    float time;
    WavePerturbStageEnum stage;
    float stageprogress;
};

class WaveBasePerturbClass;
struct WaveEmitterWarningLineStruct { vector3d start, stop; };

extern WaveBasePerturbClass *WAVE_Perturb;
extern WaveBasePerturbClass *WAVE_PerturbArray[WAVE_PerturbTypeMax];
extern WavePerturbTypeEnum WAVE_PerturbType;
extern WavePerturbStageEnum WAVE_PerturbStage;
extern WaveStageEnum WAVE_Stage;
extern WaveBreakInfoStruct WAVE_BreakInfo;
extern int WAVE_MeshStepX;
extern bool WAVE_LeftBreaker;
extern float WAVE_MeshMaxX;
extern float WAVE_MeshGridX[];
extern float WAVE_SliceGridX[];
extern WaveEmitterWarningLineStruct WAVE_EmitterWarningLine[];

void WAVE_EmitterUpdate();
void WAVE_ComputeSlices();
void WAVE_ComputeProfileCoeffs(float xmesh, float xslice, WaveProfileCoeffs &wpc, bool limit = true);
void WAVE_CheckForEmitter(const WaveProfileCoeffs &wpc, float xmesh, float xslice, WaveEmitter *we);

__asm__(".equ WAVE_Perturb, 0x0057DBD8");
__asm__(".equ WAVE_PerturbArray, 0x00484B58");
__asm__(".equ WAVE_PerturbType, 0x00484940");
__asm__(".equ WAVE_PerturbStage, 0x00585C44");
__asm__(".equ WAVE_Stage, 0x00585AD0");
__asm__(".equ WAVE_BreakInfo, 0x00585C50");
__asm__(".equ WAVE_MeshStepX, 0x00484630");
__asm__(".equ WAVE_LeftBreaker, 0x004846C4");
__asm__(".equ WAVE_MeshMaxX, 0x00484624");
__asm__(".equ WAVE_MeshGridX, 0x00485180");
__asm__(".equ WAVE_SliceGridX, 0x0048ADC0");
__asm__(".equ WAVE_EmitterWarningLine, 0x0057CC08");
__asm__(".equ WAVE_EmitterUpdate__Fv, 0x00376368");
__asm__(".equ WAVE_ComputeSlices__Fv, 0x0037A490");
__asm__(".equ WAVE_ComputeProfileCoeffs__FffR17WaveProfileCoeffsb, 0x003782C8");
__asm__(".equ WAVE_CheckForEmitter__FRC17WaveProfileCoeffsffP11WaveEmitter, 0x003841E0");

static void WAVE_EmitterInitWarnings(void)
{
    WaveProfileCoeffs wpc;
    WaveEmitter we;
    float xmesh, xslice;
    bool started;

    WaveBasePerturbClass * const OldPerturb = WAVE_Perturb;
    WavePerturbTypeEnum OldPerturbType = WAVE_PerturbType;
    WavePerturbStageEnum OldPerturbStage = WAVE_PerturbStage;
    WaveStageEnum OldStage = WAVE_Stage;
    WaveBreakInfoStruct OldBreakInfo = WAVE_BreakInfo;

    WAVE_BreakInfo.onoff = false;
    WAVE_BreakInfo.time = 1000000;
    WAVE_EmitterUpdate();

    for (WavePerturbTypeEnum type = (WavePerturbTypeEnum) 0; type < WAVE_PerturbTypeMax; ++ (int &) type)
    {
        WAVE_Perturb = WAVE_PerturbArray[type];
        WAVE_PerturbType = type;
        WAVE_PerturbStage = WAVE_PerturbStageHold;
        WAVE_Stage = WAVE_StageStable;

        WAVE_ComputeSlices();

        vector3d start(WAVE_MeshMaxX, 0, 0), stop(WAVE_MeshMaxX, 0, 0);
        started = false;
        for (int xstep = WAVE_MeshStepX; xstep >= 0; --xstep)
        {
            if (WAVE_LeftBreaker)
            {
                xmesh = WAVE_MeshGridX[WAVE_MeshStepX-xstep];
                xslice = WAVE_SliceGridX[WAVE_MeshStepX-xstep];
            }
            else
            {
                xmesh = WAVE_MeshGridX[xstep];
                xslice = WAVE_SliceGridX[xstep];
            }

            WAVE_ComputeProfileCoeffs(xmesh, xslice, wpc);
            WAVE_CheckForEmitter(wpc, xmesh, xslice, &we);

            if (!started)
            {
                if (we.type != WAVE_EM_NONE && we.type != WAVE_EM_CREST)
                {
                    start.x = we.x;
                    start.y = we.y;
                    start.z = we.z;
                    started = true;
                }
            }
            else
            {
                if (we.type == WAVE_EM_NONE || we.type == WAVE_EM_CREST)
                {
                    stop.x = we.x;
                    stop.y = we.y;
                    stop.z = we.z;
                    break;
                }
            }
        }

        if (WAVE_LeftBreaker)
        {
            WAVE_EmitterWarningLine[type].start = start;
            WAVE_EmitterWarningLine[type].stop = stop;
        }
        else
        {
            WAVE_EmitterWarningLine[type].start = stop;
            WAVE_EmitterWarningLine[type].stop = start;
        }
    }

    WAVE_Perturb = OldPerturb;
    WAVE_PerturbType = OldPerturbType;
    WAVE_PerturbStage = OldPerturbStage;
    WAVE_Stage = OldStage;
    WAVE_BreakInfo = OldBreakInfo;
    WAVE_EmitterUpdate();

    WAVE_ComputeSlices();
}
